query KeyCheck {
  reconciliationResults(first: 1) {
    edges { node { reconciliationRunResultId createdDate } }
    pageInfo { hasNextPage }
  }
}

query MorningReport {
  auditReport(audit: "month-close", date: "2026-10-08") {
    schema
    report { date period window { from thru } }
    health {
      complete
      summary
      sources { system read records reason affects }
    }
    summary { open pending newToday fixedToday }
    categories {
      id
      label
      statements {
        id
        text
        status
        counts { open pending }
        findings { id headline state firstFound ageDays records { system recordType id } }
      }
    }
  }
}

query OneFinding {
  auditFinding(id: "F-20790") {
    finding {
      id
      headline
      statement { id text }
      status { state firstFound lastSeen timesSeen pendingUntil }
      records { system recordType id internalId status }
      fix { owner where action verify { by passesWhen } darpanChanges }
      history { at event }
    }
    access { mode note }
  }
}

query OpenReturnsFindings {
  findings(first: 2, query: "category:returns state:open period:2026-10", sortKey: FIRST_FOUND) {
    edges {
      cursor
      node {
        id
        statement
        headline
        state
        firstFound
        ageDays
        records { system recordType id internalId status }
        next
      }
    }
    pageInfo { hasNextPage endCursor }
  }
}

query RecentRuns {
  reconciliationResults(first: 2, sortKey: CREATED_DATE, reverse: true, query: "statusEnumId:AUT_STAT_SUCCESS") {
    edges {
      cursor
      node { reconciliationRunResultId savedRunId differenceCount onlyInFile1Count onlyInFile2Count createdDate }
    }
    pageInfo { hasNextPage endCursor }
  }
}
